const editorialTheme=document.createElement('link');editorialTheme.rel='stylesheet';editorialTheme.href='/static/editorial-theme.css';document.head.appendChild(editorialTheme);
const conversationTheme=document.createElement('link');conversationTheme.rel='stylesheet';conversationTheme.href='/static/client-conversation.css?v=1';document.head.appendChild(conversationTheme);
const clientUser=JSON.parse(sessionStorage.getItem('shotcraftUser')||'{}');
const app=document.getElementById('app');
let timelineRequest=0;
const timelineMarkup=items=>`<section class="shared-timeline"><div class="eyebrow">Shoot journey</div><div class="timeline-track">${(items||[]).map(item=>`<div class="timeline-item ${item.completed?'complete':''}"><span class="timeline-dot">${item.completed?'✓':''}</span><div><b>${esc(item.label)}</b>${item.timestamp?`<small>${esc(new Date(item.timestamp.replace(' ','T')+'Z').toLocaleString([], {dateStyle:'medium',timeStyle:'short'}))}</small>`:'<small>Upcoming</small>'}</div></div>`).join('')}</div></section>`;
async function refreshTimeline(){const id=app.dataset.timelineId;if(!id)return;const request=++timelineRequest;try{const response=await fetch(`/api/inquiries/${id}/timeline`,{cache:'no-store'}),data=await response.json();if(request!==timelineRequest||app.dataset.timelineId!==id)return;const existing=document.querySelector('.shared-timeline');if(existing)existing.outerHTML=timelineMarkup(data.timeline);else {const legacy=document.querySelector('.steps,.detail-progress');if(legacy)legacy.outerHTML=timelineMarkup(data.timeline);else app.insertAdjacentHTML('beforeend',timelineMarkup(data.timeline))}}catch(_){} }
new MutationObserver(()=>{const form=document.getElementById('inquiryForm');if(!form||document.getElementById('deliverableCount'))return;const wardrobe=document.getElementById('wardrobe')?.closest('.field');if(!wardrobe)return;wardrobe.insertAdjacentHTML('beforebegin','<div class="field"><label>Number of final photos</label><input id="deliverableCount" type="number" min="1" max="100" value="10" required><small class="muted">Edited images you expect to receive</small></div>')}).observe(app,{childList:true,subtree:true});
let shoots=[],filter='all',current={view:'shoots',id:null},cityImages={};
document.getElementById('clientName').textContent=clientUser.name||'Client workspace';
document.getElementById('clientEmail').textContent=clientUser.email||'';
document.querySelector('.brand').innerHTML='<span class="brand-mark logo-image"><img src="/static/brand/shotcraft-mark.png" alt=""></span><span class="brand-copy"><b>ShotCraft</b><small>Creative workspace</small></span>';
document.querySelector('.identity').insertAdjacentHTML('afterbegin','<span class="profile-orb" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0"/></svg></span>');
document.querySelector('.identity').insertAdjacentHTML('beforeend','<span class="account-menu">•••</span>');
document.querySelector('.nav').innerHTML='<div class="nav-label">Workspace</div><button data-view="shoots"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 11 12 4l8 7v9h-5v-6H9v6H4Z"/></svg></span><span>Overview</span></button><button data-view="shoots" class="gallery-nav"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 6.5h16v11H4zM8 10h8M8 14h5"/></svg></span><span>Inquiries</span><span class="nav-dot"></span></button><button type="button"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M4 5h16v12H9l-5 3V5Z"/></svg></span><span>Messages</span></button><button type="button"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7 8a7 7 0 0 0-14 0"/></svg></span><span>Profile</span></button><div class="nav-label nav-create-label">Create</div><button class="create" data-view="create"><span class="nav-icon"><svg viewBox="0 0 24 24"><path d="M12 5v14M5 12h14"/></svg></span><span>New inquiry</span><span class="nav-arrow">→</span></button>';
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char]));
const parsed=value=>{try{return typeof value==='string'?JSON.parse(value):value}catch{return null}};
const payload=record=>parsed(record.payload)||{};
const formatDate=value=>{if(!value)return'Flexible date';const date=new Date(value);const hasTime=value.includes('T')||/^\d{4}-\d{2}-\d{2}\s/.test(value);return Number.isNaN(date.valueOf())?value:date.toLocaleString(undefined,{dateStyle:'medium',...(hasTime?{timeStyle:'short'}:{})})};
function statusInfo(record){if(record.status==='SCHEDULED')return['SHOOT SCHEDULED','scheduled'];if(record.status==='CLIENT_CONFIRMED')return['CONFIRMED','ready'];if(record.status==='CLIENT_CHANGE_REQUESTED')return['CHANGE REQUESTED','needs'];if(record.production_approved)return['PLAN READY','ready'];if(record.status==='NEEDS_INFORMATION')return['NEEDS YOUR INPUT','needs'];if(record.status==='READY_FOR_REVIEW')return['WITH PHOTOGRAPHER','ready'];return['IN REVIEW','']}
function title(record){const p=payload(record),analysis=parsed(record.analysis)||{},originalRequest=String(p.message||'').split(/\n\s*Client follow-up answers:|\n{2,}/i)[0].trim();return analysis.concept_name||p.shoot_type||originalRequest.split(/[.!?]/)[0]?.slice(0,64)||'Your shoot'}
function setNav(view){document.querySelectorAll('.nav button').forEach(button=>button.classList.toggle('active',(view==='create'&&button.dataset.view==='create')||(view!=='create'&&button.dataset.view==='shoots')))}
function go(view,id=null,push=true){current={view,id:id?Number(id):null};if(push){const query=new URLSearchParams();if(view!=='shoots')query.set('view',view);if(id)query.set('id',id);history.pushState(current,'','/client'+(query.size?'?'+query:''))}render()}
function nextAction(record){if(record.status==='SCHEDULED')return`<div class="next schedule"><b>Your shoot is scheduled</b>${esc(formatDate(record.call_time))} · ${esc(record.meeting_location||'Meeting location pending')}</div>`;if(record.status==='NEEDS_INFORMATION')return'<div class="next"><b>A few details are needed</b>Answer the follow-up questions to keep planning moving.</div>';if(record.production_approved)return'<div class="next"><b>Your shoot plan is ready</b>Review the plan, then confirm it or request a change.</div>';if(record.status==='CLIENT_CONFIRMED')return'<div class="next"><b>Your confirmation is with the photographer</b>They’ll add the final schedule shortly.</div>';return'<div class="next"><b>With your photographer</b>Creative planning is in progress.</div>'}
function card(record,index=0){const p=payload(record),status=statusInfo(record),city=(p.message||'').match(/Seattle|Delhi|New Delhi/i)?.[0]?.toLowerCase().replace('new delhi','delhi'),gallery=cityImages[city]?.gallery||[],image=gallery.length?gallery[index%gallery.length]:null;return`<article class="card shoot-row ${index===0?'featured':''}" ${image?`style="--tile-image:url('${image}')"`:''}><div class="shoot-visual">${image?`<img src="${image}" alt="${esc(city||'shoot')}" loading="lazy">`:''}<div class="shoot-overlay"></div><div class="shoot-date"><div class="eyebrow">${esc(formatDate(p.shoot_date))}</div><span class="status ${status[1]}">${status[0]}</span></div><h2 class="shoot-title">${esc(title(record))}</h2></div><div class="shoot-copy"><div class="meta"><span>${esc(p.message?.slice(0,150)||'')}</span></div>${nextAction(record)}</div><div class="actions shoot-actions">${record.status==='NEEDS_INFORMATION'?`<button class="primary" data-followup="${record.id}">Answer questions →</button>`:''}<button class="link" data-detail="${record.id}">View details →</button></div></article>`}
function shootsView(){setNav('shoots');const counts={action:shoots.filter(x=>x.status==='NEEDS_INFORMATION'||x.production_approved&&!['CLIENT_CONFIRMED','SCHEDULED'].includes(x.status)).length,scheduled:shoots.filter(x=>x.status==='SCHEDULED').length};const filtered=shoots.filter(record=>filter==='all'||filter==='action'&&(record.status==='NEEDS_INFORMATION'||record.production_approved&&!['CLIENT_CONFIRMED','SCHEDULED'].includes(record.status))||filter==='planning'&&['READY_FOR_REVIEW','NEW','CLIENT_CONFIRMED'].includes(record.status)||filter==='scheduled'&&record.status==='SCHEDULED');app.innerHTML=`<div class="head"><div><div class="eyebrow">Client workspace</div><h1>My shoots</h1><p class="lede">Every shoot, plan, and photographer update in one calm place.</p></div><button class="primary" data-view="create">New inquiry →</button></div><div class="summary"><span class="summary-item">${counts.action} action${counts.action===1?'':'s'} needed</span><span class="summary-item">${counts.scheduled} upcoming shoot${counts.scheduled===1?'':'s'}</span></div><div class="filters"><button class="filter ${filter==='all'?'active':''}" data-filter="all">All shoots</button><button class="filter ${filter==='action'?'active':''}" data-filter="action">Needs action</button><button class="filter ${filter==='planning'?'active':''}" data-filter="planning">In planning</button><button class="filter ${filter==='scheduled'?'active':''}" data-filter="scheduled">Scheduled</button></div><div class="shoot-list">${filtered.map((record,index)=>card(record,index)).join('')||'<div class="card empty">No shoots in this view yet.</div>'}</div>`;bind()}
async function detail(id){setNav('shoots');const record=await getRecord(id),p=payload(record),status=statusInfo(record);let heading='Your inquiry is being reviewed.',lead='Your photographer is organizing the creative direction.',state='In review',stateDetail='We’ll keep you updated here.';if(record.status==='SCHEDULED'){heading='Your shoot is scheduled.';lead='Your photographer has confirmed the final shoot details.';state='Shoot scheduled';stateDetail=`${formatDate(record.call_time)} · ${record.meeting_location||'Meeting location pending'}`}else if(record.status==='CLIENT_CONFIRMED'){heading='You’re confirmed.';lead='Your photographer will send the final schedule.';state='Shoot confirmed';stateDetail='Watch for scheduling updates.'}else if(record.status==='NEEDS_INFORMATION'){heading='One more detail from you.';lead='A few answers will help your photographer plan the right shoot.';state='Details needed';stateDetail='Answer the follow-up questions to move this forward.'}else if(record.production_approved){heading='Your shoot plan is ready.';lead='The photographer approved the production plan for your session.';state='Production plan ready';stateDetail='Review the plan, then confirm it or request a change.'}app.innerHTML=`<button class="link" data-view="shoots">← Back to My shoots</button><div class="detail-head"><div class="eyebrow">Shoot details · #${record.id}</div><h1>${heading}</h1><p class="lede">${lead}</p></div><section class="card"><div class="state"><div class="check">✓</div><div><strong>${state}</strong><p>${esc(stateDetail)}</p></div></div><div class="steps"><div class="step done"><b>01 · Inquiry</b>Details captured</div><div class="step ${record.status!=='NEW'?'done':''}"><b>02 · Planning</b>Creative review</div><div class="step ${record.production_approved||record.status==='SCHEDULED'?'done':''}"><b>03 · Confirm</b>Plan and schedule</div></div><div class="actions">${record.status==='NEEDS_INFORMATION'?`<button class="primary" data-followup="${id}">Answer questions →</button>`:''}${record.production_approved?`<button class="primary" data-plan="${id}">Review shoot plan →</button>`:''}${record.production_approved&&!['CLIENT_CONFIRMED','SCHEDULED'].includes(record.status)?`<button class="secondary" data-confirm="${id}">Confirm this plan</button><button class="secondary" data-change="${id}">Request a change</button>`:''}</div></section><section class="card"><div class="eyebrow">Your inquiry</div><h2 class="shoot-title">${esc(title(record))}</h2><p class="muted">${esc(p.message||'')}</p></section>`;bind()}
async function followup(id){setNav('shoots');const record=await getRecord(id),analysis=parsed(record.analysis)||{},questions=analysis.questions||[];app.innerHTML=`<button class="link" data-detail="${id}">← Back to shoot details</button><div class="detail-head"><div class="eyebrow">Shoot follow-up</div><h1>A few details for your shoot.</h1><p class="lede">Your answers help your photographer make the plan more specific.</p></div><section class="card">${analysis.summary?`<p class="muted">${esc(analysis.summary)}</p>`:''}${questions.length?`<ol>${questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol>`:''}<form id="followupForm"><div class="field"><label for="answers">Your answers</label><textarea id="answers" required placeholder="Write your answers here…"></textarea></div><div class="actions"><button class="primary" id="sendAnswers">Send answers →</button><span id="replyStatus" class="muted"></span></div></form></section>`;bind();document.getElementById('followupForm').onsubmit=event=>reply(event,id)}
async function reply(event,id){event.preventDefault();const button=document.getElementById('sendAnswers'),status=document.getElementById('replyStatus');button.disabled=true;status.textContent='Sending your answers…';try{const response=await fetch(`/api/inquiries/${id}/reply`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answers:document.getElementById('answers').value})});if(!response.ok)throw Error();status.textContent='Answers received. Updating your shoot…';for(let attempt=0;attempt<20;attempt++){await new Promise(resolve=>setTimeout(resolve,1500));const record=await fetch(`/api/inquiries/${id}`).then(r=>r.json());if(record.status!=='NEW'){await refresh();detail(id);return}}await refresh();detail(id)}catch{status.textContent='Could not send your answers. Please try again.';button.disabled=false}}
async function plan(id){setNav('shoots');const record=await getRecord(id),pack=parsed(record.production_pack);if(!pack){detail(id);return}app.innerHTML=`<button class="link" data-detail="${id}">← Back to shoot details</button><div class="detail-head"><div class="eyebrow">Approved shoot plan</div><h1>${esc(pack.title)}</h1><p class="lede">Everything your photographer prepared for the session.</p></div><section class="card"><div class="eyebrow">Call sheet</div><div class="call-sheet">${Object.entries(pack.call_sheet||{}).map(([k,v])=>`<div><small>${esc(k)}</small><b>${esc(v)}</b></div>`).join('')}</div></section><div class="plan-grid">${section('Location plan',pack.location_plan)}${section('Shot list',pack.shot_list)}${section('Lighting plan',pack.lighting_plan)}${section('Wardrobe checklist',pack.wardrobe_checklist)}${section('Weather note',[pack.weather_note])}${section('Backup plan',[pack.backup_plan])}</div>`;bind()}
const section=(title,values)=>`<section class="card"><div class="eyebrow">${title}</div><ul>${(values||[]).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></section>`;
function create(){setNav('create');app.innerHTML=`<div class="head"><div><div class="eyebrow">New inquiry</div><h1>Tell us what you’re imagining.</h1><p class="lede">Start with the essentials. Your account details are already included.</p></div></div><section class="card"><form id="inquiryForm"><div class="form-grid"><div class="field"><label>Your name</label><input value="${esc(clientUser.name)}" readonly></div><div class="field"><label>Email address</label><input value="${esc(clientUser.email)}" readonly></div><div class="field"><label>Preferred shoot date</label><input id="date" type="date"></div><div class="field"><label>Estimated budget</label><input id="budget" type="number" min="0" step="50" placeholder="$ 500"></div><div class="field"><label>Who is the shoot for?</label><select id="subject"><option value="woman">A woman</option><option value="man">A man</option><option value="non-binary person">A non-binary person</option><option value="group">A group</option><option value="no person / product or location">No person</option></select></div><div class="field"><label>Number of people</label><input id="count" type="number" min="1" max="10" value="1"></div><div class="field full"><label>Wardrobe details</label><input id="wardrobe" placeholder="e.g. navy polo, black jeans, black boots"></div><div class="field"><label for="photographer">Choose a photographer</label><select id="photographer" required disabled><option value="">Loading available photographers…</option></select><small class="muted" id="photographerHelp">Choose who should receive this inquiry.</small></div><div class="field full"><label>What are you picturing?</label><textarea id="message" required placeholder="Describe the mood, location, purpose, wardrobe, or anything else that matters…"></textarea></div></div><div class="actions"><button class="primary" id="sendInquiry">Send my inquiry →</button><span id="formStatus" class="muted"></span></div></form></section>`;bind();document.getElementById('inquiryForm').onsubmit=submitInquiry;populatePhotographers()}
async function populatePhotographers(){const select=document.getElementById('photographer'),help=document.getElementById('photographerHelp'),submit=document.getElementById('sendInquiry');if(!select)return;try{const response=await fetch('/api/photographers',{cache:'no-store'});if(!response.ok)throw Error();const photographers=await response.json();if(!photographers.length){select.innerHTML='<option value="">No photographers are available yet</option>';help.textContent='Ask a photographer to create a ShotCraft workspace first.';if(submit)submit.disabled=true;return}select.innerHTML=`<option value="" selected disabled>Select a photographer…</option>${photographers.map(person=>`<option value="${esc(person.email)}">${esc(person.name)} · ${esc(person.email)}</option>`).join('')}`;select.disabled=false;help.textContent=`${photographers.length} photographer${photographers.length===1?'':'s'} available to receive your inquiry.`}catch{select.innerHTML='<option value="">Could not load photographers</option>';help.textContent='Refresh the page and try again.';if(submit)submit.disabled=true}}
async function submitInquiry(event){event.preventDefault();const button=document.getElementById('sendInquiry'),status=document.getElementById('formStatus');button.disabled=true;status.textContent='Sending your inquiry…';try{const response=await fetch('/api/inquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({client_name:clientUser.name,client_email:clientUser.email,contact_email:clientUser.email,message:document.getElementById('message').value,budget:Number(document.getElementById('budget').value)||null,shoot_date:document.getElementById('date').value||null,reference_images:[],photographer_email:document.getElementById('photographer').value,subject_presentation:document.getElementById('subject').value,subject_count:Number(document.getElementById('count').value)||1,wardrobe_details:document.getElementById('wardrobe').value||null,deliverable_count:Number(document.getElementById('deliverableCount').value)||null})});if(!response.ok)throw Error();const created=await response.json();current={view:'details',id:Number(created.id)};history.pushState(current,'',`/client?view=details&id=${created.id}`);app.innerHTML='<div class="loading">Reviewing your inquiry and preparing any follow-up questions…</div>';for(let attempt=0;attempt<40;attempt++){await new Promise(resolve=>setTimeout(resolve,1500));const record=await getRecord(created.id);if(record.status!=='NEW'){await refresh();galleryDetail(created.id);return}}await refresh();galleryDetail(created.id)}catch{status.textContent='We couldn’t send that just yet. Please try again.';button.disabled=false}}
async function decision(id,endpoint,note=''){const response=await fetch(`/api/inquiries/${id}/${endpoint}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note})});if(response.ok){await refresh();current={view:'details',id:Number(id)};galleryDetail(id)}}
function bind(){document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;shootsView()});document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>go('details',b.dataset.detail));document.querySelectorAll('[data-followup]').forEach(b=>b.onclick=()=>go('followup',b.dataset.followup));document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>go('plan',b.dataset.plan));document.querySelectorAll('[data-confirm]').forEach(b=>b.onclick=()=>decision(b.dataset.confirm,'client-confirm'));document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{const note=prompt('What would you like to change?');if(note!==null)decision(b.dataset.change,'client-change-request',note)})}
async function getRecord(id){const record=await fetch(`/api/inquiries/${id}`,{cache:'no-store'}).then(r=>r.json()),index=shoots.findIndex(x=>x.id==id);if(index>=0)shoots[index]=record;return record}
async function refresh(){const response=await fetch('/api/inquiries?client_email='+encodeURIComponent(clientUser.email||''));shoots=await response.json();shoots.sort((a,b)=>{const priority=x=>x.status==='NEEDS_INFORMATION'?0:x.production_approved&&!['CLIENT_CONFIRMED','SCHEDULED'].includes(x.status)?1:x.status==='SCHEDULED'?3:2;return priority(a)-priority(b)||b.id-a.id})}
function galleryCard(record,index=0){const p=payload(record),status=statusInfo(record),city=(p.message||'').match(/Seattle|Delhi|New Delhi/i)?.[0]?.toLowerCase().replace('new delhi','delhi'),gallery=cityImages[city]?.gallery||[],image=gallery.length?gallery[index%gallery.length]:null,location=city==='delhi'?'Delhi, India':city==='seattle'?'Seattle, Washington':'Location being planned';return`<article class="gallery-card ${index===0?'gallery-featured':''}">${image?`<img src="${image}" alt="${esc(location)} city view" loading="lazy">`:''}<div class="gallery-shade"></div><button class="circle-action" data-detail="${record.id}" aria-label="View ${esc(title(record))}">→</button><div class="gallery-content"><h2>${esc(title(record))}</h2><div class="gallery-meta"><span>▣ ${esc(formatDate(p.shoot_date))}</span><span>⌖ ${esc(location)}</span></div><span class="status ${status[1]}">${status[0]}</span>${index===0?`<button class="primary gallery-cta" data-detail="${record.id}">View shoot details →</button>`:`<button class="link gallery-link" data-detail="${record.id}">View details →</button>`}</div></article>`}
function galleryView(){setNav('shoots');document.querySelectorAll('.nav button').forEach(button=>button.classList.remove('active'));document.querySelector('.gallery-nav')?.classList.add('active');const visible=shoots;app.innerHTML=`<div class="gallery-shell"><div class="gallery-grid">${visible.map((record,index)=>galleryCard(record,index)).join('')}<button class="gallery-card new-inquiry-card" data-view="create"><div class="gallery-shade"></div><span class="circle-action">→</span><div class="gallery-content"><h2>New inquiry</h2><p>Start planning your next shoot.</p><span class="gallery-link">Create inquiry →</span></div></button></div></div>`;bind()}
async function galleryDetail(id){setNav('shoots');document.querySelectorAll('.nav button').forEach(button=>button.classList.remove('active'));document.querySelector('.gallery-nav')?.classList.add('active');const record=await getRecord(id),p=payload(record),status=statusInfo(record),city=(p.message||'').match(/Seattle|Delhi|New Delhi/i)?.[0]?.toLowerCase().replace('new delhi','delhi'),gallery=cityImages[city]?.gallery||[],location=record.meeting_location||(city==='delhi'?'Delhi, India':city==='seattle'?'Seattle, Washington':'Location being planned'),date=record.call_time||p.shoot_date,scheduled=record.status==='SCHEDULED',planning=record.status!=='NEW',confirmed=record.production_approved||['CLIENT_CONFIRMED','SCHEDULED'].includes(record.status);let actions='';if(record.status==='NEEDS_INFORMATION')actions=`<button class="primary" data-followup="${id}">Answer questions →</button>`;else if(record.production_approved)actions=`<button class="primary" data-plan="${id}">Review shoot plan →</button>`;else actions='<button class="secondary" type="button">Message photographer</button>';app.innerHTML=`<div class="detail-gallery"><div class="detail-top"><div><button class="link detail-crumb" data-view="shoots">Inquiries</button><span> / ${esc(title(record))}</span><h1>${esc(title(record))}</h1></div><button class="circle-action detail-back" data-view="shoots" aria-label="Back to inquiries">←</button></div><div class="detail-strip">${gallery.slice(0,5).map((image,index)=>`<img src="${image}" alt="${esc(location)} reference ${index+1}">`).join('')||'<div class="detail-placeholder">Creative references are being prepared.</div>'}</div><div class="detail-progress"><div class="done"><i>✓</i><b>Inquiry</b><span>${esc(formatDate(p.shoot_date))}</span></div><div class="${planning?'done current':''}"><i>2</i><b>Creative review</b><span>${planning?'In progress':'Pending'}</span></div><div class="${confirmed?'done':''}"><i>3</i><b>${scheduled?'Scheduled':'Confirmation'}</b><span>${scheduled?esc(formatDate(record.call_time)):'Pending'}</span></div></div><section class="detail-sheet"><div class="detail-facts"><div><span>▣ Date</span><b>${esc(formatDate(date))}</b></div><div><span>◷ Time</span><b>${record.call_time?esc(new Date(record.call_time).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})):'To be confirmed'}</b></div><div><span>⌖ Location</span><b>${esc(location)}</b></div><div><span>♙ Photographer</span><b>${esc(p.photographer_email||'Your ShotCraft photographer')}</b></div></div><div class="detail-next"><p>${scheduled?'Your shoot is confirmed. Review the plan, location, and final details before the session.':record.production_approved?'Your photographer has prepared the creative plan. Review it and confirm when you are ready.':'Your photographer is shaping the creative direction. Updates will appear here.'}</p><div class="actions">${actions}<button class="secondary" type="button">Message photographer</button></div></div></section></div>`;bind()}
function planBlock(titleText,value,icon){const values=Array.isArray(value)?value:[value];return`<section class="plan-block"><div class="plan-icon">${icon}</div><h3>${esc(titleText)}</h3><ul>${values.filter(Boolean).map(item=>`<li>${esc(typeof item==='object'?JSON.stringify(item):item)}</li>`).join('')||'<li>Details will be added by your photographer.</li>'}</ul></section>`}
